import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"Troubleshooting quickstart","description":"Source connection failures, stale data, missing portfolio totals, API/backend availability, and safe credential guidance.","frontmatter":{"title":"Troubleshooting quickstart","description":"Source connection failures, stale data, missing portfolio totals, API/backend availability, and safe credential guidance.","audience":"user","status":"current","last_verified":"2026-07-19T00:00:00.000Z"},"headers":[],"relativePath":"get-started/troubleshooting-quickstart.md","filePath":"get-started/troubleshooting-quickstart.md","lastUpdated":null}'),o={name:"get-started/troubleshooting-quickstart.md"};function r(n,e,l,c,d,u){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="troubleshooting-quickstart" tabindex="-1">Troubleshooting quickstart</h1><p>Common first-run issues and what to check.</p><h2 id="source-connection-failures" tabindex="-1">Source connection failures</h2><ul><li><strong>Brokerage (SnapTrade)</strong>: re-authenticate through the broker; confirm you authorized read-only access. SnapTrade supports a subset of brokers — if yours is missing, the connection cannot complete.</li><li><strong>Exchange API key rejected</strong>: Zenin rejects keys with trade or withdraw permission. Create a <strong>read-only</strong> key and retry.</li><li><strong>Hyperliquid watch-only</strong>: confirm the address is a valid public address; no secret is required.</li><li>Check <strong>Notifications</strong> for a source-health notice with the specific reason.</li></ul><h2 id="stale-or-missing-data" tabindex="-1">Stale or missing data</h2><ul><li>Open <strong>Portfolio</strong> and check each position&#39;s <strong>freshness state</strong>.</li><li><strong>Stale / delayed</strong> means the last refresh is old or the source provides delayed data — not a bug.</li><li><strong>Unavailable / reference-only</strong> means the source did not return a live value; Zenin shows the state instead of a fabricated number.</li><li>Data coverage varies by instrument and provider; some assets simply have no live feed.</li></ul><h2 id="missing-portfolio-totals" tabindex="-1">Missing portfolio totals</h2><ul><li>Confirm the connection completed and the first sync ran (see <a href="/get-started/first-portfolio-sync">First portfolio sync</a>).</li><li>Add <strong>manual positions</strong> for anything outside your connections.</li><li>If the same instrument appears in two sources, expect a <strong>duplicate-exposure warning</strong> rather than a doubled total — the unified view reconciles it.</li></ul><h2 id="api-backend-availability" tabindex="-1">API / backend availability</h2><ul><li>If the app cannot load workspace data, the backend API may be unavailable. Check the service status or your network.</li><li>Retry the action after a short wait; Zenin retries source syncs per each source&#39;s retry behavior.</li></ul><h2 id="safe-credential-guidance" tabindex="-1">Safe credential guidance</h2><ul><li>Never paste broker <strong>passwords</strong> into Zenin. Use SnapTrade or read-only API keys.</li><li>Use <strong>read-only</strong> exchange keys; never trade/withdraw-enabled keys.</li><li>For Hyperliquid, use a <strong>public watch-only address</strong> — no secret needed.</li><li>Do not commit keys to repositories or share them in support threads.</li></ul><p>If you are still blocked, note the exact asset, source, and the freshness/error state shown, then contact support.</p>',13)])])}const p=t(o,[["render",r]]);export{g as __pageData,p as default};
